/// <summary>
///     Data Contract class for <c>AVABOSProvisionReportContract</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Data Contract class for the <c>AVABOSProvisionReport</c> SSRS Report.
/// </remarks>
[
    DataContractAttribute,
    /*
    SysOperationGroupAttribute("SalesQuotationTable", literalStr("@NDX:NXAQuotations"), "1", FormArrangeMethod::Vertical),
    SysOperationGroupAttribute("KCS_KBVRequestTable", literalStr("@NDX:NXARequests"),   "2", FormArrangeMethod::Vertical)
    //SysOperationGroupAttribute("TransactionValues", "@Retail:Transactions", "3", FormArrangeMethod::Vertical)
    */
    SysOperationGroupAttribute("Parameters", literalStr("@SYS28007"), "1", FormArrangeMethod::Vertical)
]
    public class AVABOSProvisionReportContract implements SysOperationValidatable
{
    CreatedTransactionId        contractCreatedTransactionId;

//    AVAEvaluationDate           contractAVAEvaluationDate;

    // Parameters
    AVAEvaluationDateFrom       contractAVAEvaluationDateFrom;
    AVAEvaluationDateTo         contractAVAEvaluationDateTo;
    AVASumInvoicePositions      contractPrintMode;

    AVACBSRecipientRelation     contractRecipientAC;
    AVACBSBasicRecipientType    contractRecipientType;
    CustAccount                 contractCustAccount;
//    AVADetailedSummarized       contractPrintMode;

    str                         packedQuery;


}

